window.RP_SESSION={"id":"S-c61317ff99f2","messages":[{"id":"RP-II-0180341","time":"2026-09-05T11:55:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"그가 가고, 다시 혼자가 된 위크.\n\n\"쩝... 심심하구만.\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180342","time":"2026-09-05T11:56:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"누구 없나?\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180343","time":"2026-09-05T11:59:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"두리번 두리번","characters":["P-d129df648db5"]},{"id":"RP-II-0180344","time":"2026-09-05T12:41:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"흥~ 흥 흐응~\"\n\n콧노래를 부르며 길드문을 나서던 타냐.\n\n\"얼레? 여기서 뭐한담. 진실의 의자?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180345","time":"2026-09-05T12:41:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"음악의 의자라고 불러줘, 아가씨.\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180346","time":"2026-09-05T12:42:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"음악의 의자? 흠.\"\n\n\"거기 앉아있으면 음악이 줄줄 나오나?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180347","time":"2026-09-05T12:43:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"어, 그리고 내가 앉는 의자는 모두 음악의 의자가 된다고.\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180348","time":"2026-09-05T12:43:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"지금은 무슨 음악이 나오는데?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180349","time":"2026-09-05T12:45:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"글쎄, 한창 외로웠는데 손님이 왔으니 반가운 음악?\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180350","time":"2026-09-05T12:45:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"현을 튕깁니다. 디리리리링~","characters":["P-d129df648db5"]},{"id":"RP-II-0180351","time":"2026-09-05T12:47:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"오. 연주해주는 거야? 잠깐만.\"\n\n그녀는 벽에 기대고는 손에서 푸른 빛을 내며 박수를 두어번 짝짝.\n\n그리고는 눈을 감았습니다.\n\n\"준비됐어.\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180352","time":"2026-09-05T12:48:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"기타 몸체를 텅텅 두드려 보고는, 크흠 헛기침을 하더니... 빠른 핑거스타일 연주가 들려옵니다.","characters":["P-d129df648db5"]},{"id":"RP-II-0180353","time":"2026-09-05T12:49:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"아이....\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180354","time":"2026-09-05T12:49:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"폰시!\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180355","time":"2026-09-05T12:49:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"https://youtu.be/kJQP7kiw5Fk?si=lyIb2oFExiEc-dVg","characters":["P-d129df648db5"]},{"id":"RP-II-0180356","time":"2026-09-05T12:52:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그녀는 팔짱을 낀 채 고개를 까딱까딱...\n\n베일이 리듬에 맞춰 찰랑거립니다. 연주가 끝나자.\n\n\"노래가 예쁘네. 무슨 내용이야?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180357","time":"2026-09-05T12:53:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"크흠, 내용이 중요해? 노래만 좋으면 그만이지.\"\n\n그렇게 생각하진 않다만, 애써 언급을 피합니다.","characters":["P-d129df648db5"]},{"id":"RP-II-0180358","time":"2026-09-05T12:54:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...흐흥. 남국 노래 같은데... 좀 이상한 거구나?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180359","time":"2026-09-05T12:54:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"남쪽 애들이 다 그렇지 뭐.\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180360","time":"2026-09-05T12:56:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그래? 한번 갔다왔는데 재밌긴 하더라. 에너지가 느껴진다고 해야하나?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180361","time":"2026-09-05T12:58:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"다녀왔어? 그럼 이 노래도 알겠네.\"\n\n기타를 두드리며 베이스, 핑거스냅 포인트.\n\n세뇨리따.","characters":["P-d129df648db5"]},{"id":"RP-II-0180362","time":"2026-09-05T12:59:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"https://youtu.be/Pkh8UtuejGw?si=5LnonwrCrIO4AbZC","characters":["P-d129df648db5"]},{"id":"RP-II-0180363","time":"2026-09-05T13:02:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"음악의 의자 효과 엄청 좋네.\"\n\n\"들어 본 적 없어. 일주일 정도 놀다가 왔는데 엄청 휴양지 같은 분위기였거든.\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180364","time":"2026-09-05T13:03:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"그래? 아쉽네. 원랜 듀엣곡이거든.\"\n\n그녀가 모르니, 어쩔 수 없이 혼자서 부른 위크","characters":["P-d129df648db5"]},{"id":"RP-II-0180365","time":"2026-09-05T13:05:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"음악에 관심이 없었어서 말이야. 근데 노래 몇개나 악기 하나쯤 할 줄 아는 것도 재밌을 거 같아.\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180366","time":"2026-09-05T13:05:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"악기는 어려워도, 노래는 몇 개쯤 외워 두라고. 힘들 때나 즐거울 때나 함께할 테니.\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180367","time":"2026-09-05T13:07:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그런가봐. 머챈트한테 배워둘까?\"\n\n\"그리고... 넌 왜 하필 음악이야?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180368","time":"2026-09-05T13:10:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"좋아서지. 뭐, 다른 이유가 필요한가?\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180369","time":"2026-09-05T13:12:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"흠... 이유는 필요는 없지. 맞아.\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180370","time":"2026-09-05T13:12:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그냥 이끌려서?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180371","time":"2026-09-05T13:12:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"그런 셈이지.\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180372","time":"2026-09-05T13:12:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"다음부턴 그렇게 얘기해. 그쪽이 더 낭만적으로 들리잖아.\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180373","time":"2026-09-05T13:13:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"이끌린다는 건 수동적인 거잖아?\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180374","time":"2026-09-05T13:15:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그래? 그럼 너는 뭔데? 네가 음악에게 갈 뿐이야?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180375","time":"2026-09-05T13:18:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"당연하지. 난 내 의지로 간 거라구.\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180376","time":"2026-09-05T13:21:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그래서 음악으로 뭘 하고 싶은건데?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180377","time":"2026-09-05T13:21:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"음악은 수단이 아냐. 그냥 그 자체를 즐기는 거지.\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180378","time":"2026-09-05T13:21:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"왜, 나에 대해 좀 궁금하신가?\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180379","time":"2026-09-05T13:22:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"흠. 내가 너한테 작업 부리는 거 같은 멘트는 관둬줄래?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180380","time":"2026-09-05T13:23:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그냥, 신기하잖아.\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180381","time":"2026-09-05T13:25:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"아쉽네, 나한테 관심있는 여자는 사기꾼 아니면 X녀뿐이라는 법칙이 깨질 뻔 했는데 말야.\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180382","time":"2026-09-05T13:28:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"으휴. 도끼병이야 그거. 딴따라들은 세상 인기가 다 자기 건 줄 안다니까.\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180383","time":"2026-09-05T13:31:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"내가 도끼병이라고? 지나가던 개가 웃겠다. 그랬으면 내 음악이 여자 꼬시는 데나 쓰이지 않았겠어? 남정네들 환장하는 음악이 아니라 말야.\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180384","time":"2026-09-05T13:34:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"지나가던 개는 웃겼대? 다행이네.\"\n\n\"아무튼, 요즘 길드에 음유시인들이 많이 들어오더라고?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180385","time":"2026-09-05T13:36:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"그래? 인사차 한번 들러야겠네\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180386","time":"2026-09-05T13:38:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"얼굴도 볼 겸.\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180387","time":"2026-09-05T13:38:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"흠. 난 잘 모르겠어. 딴따라들이 용병 길드에 많아봤자 뭘 한담? 두 세명이 적당할 거 같은데.\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180388","time":"2026-09-05T13:40:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"그렇긴 하지. 나처럼 하아아드한 전투음악을 하는 사람만 있으면 되지 않겠어?\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180389","time":"2026-09-05T13:43:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\".....?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180390","time":"2026-09-05T13:43:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"막 싸울 때도 연주하고 있어?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180391","time":"2026-09-05T13:49:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"아니, 그정도로 쌈을 잘하진 않고...\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180392","time":"2026-09-05T13:49:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"그만큼 음악이 전투적이다 이거지.\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180393","time":"2026-09-05T13:50:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"전투음악이란 건 전투할 때 쓸 수 없구나...\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180394","time":"2026-09-05T14:00:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"당연하지..\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180395","time":"2026-09-05T14:04:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...스읍... 낭만 좀 없는데?\"\n\n\"막... 죽기 직전까지 연주를 하고 싶다던가... 그런 거 없어?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180396","time":"2026-09-05T14:35:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"글쎄다, 살기도 바쁜데 죽음까지 왜 생각해?\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180397","time":"2026-09-05T15:28:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"글쎄. 엔딩 정도는 나 스스로 정하고 싶을지도?\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180398","time":"2026-09-05T16:11:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"그럴 수도 있지.\"","characters":["P-d129df648db5"]},{"id":"RP-II-0180399","time":"2026-09-05T16:16:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"다를 수도 있고.\"\n\n어깨를 으쓱.\n\n\"나중에 노래 또 들려줘.\"","characters":["P-b15cb9756a04"]},{"id":"RP-II-0180400","time":"2026-09-05T17:16:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"굿바이.\"\n\n손을 흔듭니다.","characters":["P-d129df648db5"]},{"id":"RP-II-0180401","time":"2026-09-05T17:17:00+09:00","room":"RP II","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-d129df648db5"]},{"id":"RP-II-0180402","time":"2026-09-05T17:17:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
